INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(4901, 'Deuteronomy 15:16', 'Deuteronomy', 15, 16, '&nbsp;خو کېدے شى چې ستاسو غلام ونۀ غواړى چې لاړ شى، او هغه ستاسو او ستاسو خاندان سره مينه کوى او د هغۀ دپاره ستاسو سره پاتې کېدل ښۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4902, 'Deuteronomy 15:17', 'Deuteronomy', 15, 17, '&nbsp;نو د خپل کور دروازې ته هغه بوځئ او هلته د هغۀ غوږ سورے کړئ، نو هغه به ټول عُمر ستاسو غلام وى. د خپلې وينځې سره هم دغه شان سلوک کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4903, 'Deuteronomy 15:18', 'Deuteronomy', 15, 18, '&nbsp;کله چې تاسو يو غلام آزادوئ نو خفه کېږئ مه، ځکه چې آخر هغۀ هم د يو مزدور په نيم قيمت شپږ کاله ستاسو خِدمت کړے دے. هم دغه شان کوئ، نو مالِک خُدائ ستاسو خُدائ پاک به په هر کار کښې تاسو له برکت درکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4904, 'Deuteronomy 15:19', 'Deuteronomy', 15, 19, '&nbsp;د خپل څاروى يا ګډې هر يو وړومبے نر بچے مالِک خُدائ ستاسو خُدائ پاک دپاره بېل کړئ، د دې څاروو نه يو هم د کار دپاره مۀ استعمالوئ او د دې ګډو نه وړۍ مۀ کټ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4905, 'Deuteronomy 15:20', 'Deuteronomy', 15, 20, '&nbsp;تاسو، او ستاسو خاندان به هر کال د عبادت په يو ځائ کښې د مالِک خُدائ په حضور کښې دا خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4906, 'Deuteronomy 15:21', 'Deuteronomy', 15, 21, '&nbsp;خو کۀ په يو ځناور کښې څۀ عېب وى، کۀ هغه ګوډ وى، ړوند يا څۀ بل غټ نقص په کښې وى، نو تاسو به هغه مالِک خُدائ خپل خُدائ پاک ته نۀ قربانى کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4907, 'Deuteronomy 15:22', 'Deuteronomy', 15, 22, '&nbsp;داسې ځناور تاسو په خپل کور کښې خوړے شئ، ستاسو هر يو کس، کۀ پاک وى يا ناپاک، نو دا خوړلے شى، لکه څنګه چې تاسو هوسۍ يا غرڅۍ خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4908, 'Deuteronomy 15:23', 'Deuteronomy', 15, 23, '&nbsp;خو د دې وينه د خوراک دپاره مۀ استعمالوئ، او خامخا يې د اوبو په شان په زمکه تويَوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4909, 'Deuteronomy 16:1', 'Deuteronomy', 16, 1, '&nbsp;د ابيب په مياشت کښې د فسحې اختر کولو سره د مالِک خُدائ خپل خُدائ پاک درناوے کوئ، دا هغه مياشت وه چې مالِک خُدائ ستاسو خُدائ پاک تاسو د مِصر نه د شپې راوويستلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4910, 'Deuteronomy 16:2', 'Deuteronomy', 16, 2, '&nbsp;د مالِک خُدائ خپل خُدائ پاک د فسحې اختر د قربانۍ دپاره هلته خپل يو ګډ يا يو څاروے حلال کړئ کوم ځائ چې هغۀ د خپل نوم د درناوى دپاره خوښ کړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4911, 'Deuteronomy 16:3', 'Deuteronomy', 16, 3, '&nbsp;کله چې تاسو دا خوراک وخورئ، نو خمبيره شوې روټۍ به نۀ خورئ. اووۀ ورځې به تاسو پتيره روټۍ خورئ، هم هغه شان لکه څنګه چې تاسو د مِصر نه په تېزۍ سره راووتلئ. دا روټۍ خورئ او د دې نوم به د تکليفونو روټۍ وى، چې تر کومې پورې تاسو ژوندى يئ نو ستاسو به هغه ورځ ياده وى چې د مِصر مُلک نه راوتلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4912, 'Deuteronomy 16:4', 'Deuteronomy', 16, 4, '&nbsp;اووۀ ورځې به ستاسو په مُلک کښې د هيچا په کور کښې خمبيره نۀ وى، او د وړومبۍ ورځې په ماښام د حلال شوى ځناور غوښه به هم په هغه شپه خوړلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4913, 'Deuteronomy 16:7', 'Deuteronomy', 16, 7, '&nbsp;غوښه ويشوئ او د عبادت په هغه يو ځائ کښې يې وخورئ، او په ورپسې سحر واپس کور ته راشئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4914, 'Deuteronomy 16:8', 'Deuteronomy', 16, 8, '&nbsp;ورپسې شپږ ورځې به تاسو پتيره روټۍ خورئ او په اوومه ورځ د مالِک خُدائ خپل خُدائ پاک د عبادت دپاره راغونډ شئ او په هغه ورځ کار مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4915, 'Deuteronomy 16:9', 'Deuteronomy', 16, 9, '&nbsp;چې تاسو د فصل رېبل شروع کړئ نو د هغه وخت نه اووۀ هفتې وشمېرئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4916, 'Deuteronomy 16:10', 'Deuteronomy', 16, 10, '&nbsp;او بيا د مالِک خُدائ ستاسو خُدائ پاک درناوى دپاره د لَو کولو اختر وکړئ، هغۀ چې کوم برکت درکړے دے د هغې په مطابق هغۀ له يوه رضاکارانه نذرانه راوړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4917, 'Deuteronomy 16:11', 'Deuteronomy', 16, 11, '&nbsp;د مالِک خُدائ په حضور کښې تاسو سره د خپلو بچو، ستاسو نوکرانو، ليويانو، مسافرو، يتيمانانو او د هغه کونډو سره خوشحاله شئ چې ستاسو په ښارونو کښې اوسيږى. د عبادت په هغه يو ځائ کښې هم دغه شان کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4918, 'Deuteronomy 16:12', 'Deuteronomy', 16, 12, '&nbsp;ګورئ چې په دې حُکمونو باندې عمل وکړئ، دا خبره مۀ هېروئ چې تاسو په مِصر کښې غلامان وئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4919, 'Deuteronomy 16:13', 'Deuteronomy', 16, 13, '&nbsp;چې تاسو خپل ټول فصل راټول کړئ او خپل ټول انګور په لنګرۍ کښې نچوړ کړئ، نو اووۀ ورځې د جونګړو اختر کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4920, 'Deuteronomy 16:14', 'Deuteronomy', 16, 14, '&nbsp;تاسو د خپلو بچو سره، خپلو نوکرانو او د ليويانو، مسافرو، يتيمانانو او د هغه کونډو سره د دې نه خوند واخلئ چې ستاسو په ښارونو کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4921, 'Deuteronomy 16:15', 'Deuteronomy', 16, 15, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک چې کوم ځائ خوښ کړے وى نو په هغه ځائ کښې اووۀ ورځې اختر وکړئ. خوشحاله اوسئ، ځکه چې مالِک خُدائ ستاسو فصل او ستاسو کار له برکت ورکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4922, 'Deuteronomy 16:16', 'Deuteronomy', 16, 16, '&nbsp;ستاسو د قوم ټول سړى به په کال کښې درې ځل د مالِک خُدائ عبادت دپاره هغه يو ځائ ته يعنې د فسحې اختر، د لَو کولو اختر او د جونګړو اختر دپاره راځى. او يو سړے به هم مالِک خُدائ له خالى لاسونه نۀ راځى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4923, 'Deuteronomy 16:17', 'Deuteronomy', 16, 17, '&nbsp;او د هر چا چې څومره وس وى، نو هغه به د هم هغه برکت په مطابق هديه ورکوى څومره چې مالِک خُدائ خپل خُدائ پاک هغۀ له ورکړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4924, 'Deuteronomy 16:18', 'Deuteronomy', 16, 18, '&nbsp;په هر يو ښار کښې چې مالِک خُدائ ستاسو خُدائ پاک يې درکوى په هغې کښې قاضيان او نور آفسران مقرر کړئ. دا سړى به د چا د طرفدارۍ نه بغېر فېصلې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4925, 'Deuteronomy 16:19', 'Deuteronomy', 16, 19, '&nbsp;هغوئ به په خپلو فېصلو کښې د بې‌اِنصافۍ نه کار نۀ اخلى، او رشوت دې نۀ اخلى، ځکه چې رشوت هوښيار خلق ړندوى او د صادقانو په خبرو کښې چالاکى پېدا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4926, 'Deuteronomy 16:20', 'Deuteronomy', 16, 20, '&nbsp;همېشه عدل او اِنصاف کوونکى اوسئ، نو چې هغه مُلک قبضه کړئ چې مالِک خُدائ ستاسو خُدائ پاک يې تاسو له درکوى او هلته اوسېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4927, 'Deuteronomy 16:21', 'Deuteronomy', 16, 21, '&nbsp;کله چې تاسو مالِک خُدائ خپل خُدائ پاک دپاره يوه قربان‌ګاه جوړَوئ، نو د هغې په څنګ کښې د لرګى د اشيرې بُت ستنه مۀ ودروئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4928, 'Deuteronomy 16:22', 'Deuteronomy', 16, 22, '&nbsp;او د بُت پرستۍ دپاره د کاڼى ستنه مۀ ودروئ، مالِک خُدائ د دې څيزونو نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4929, 'Deuteronomy 17:1', 'Deuteronomy', 17, 1, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک ته داسې يو څاروے يا ګډ هم مۀ قربانى کوئ چې څۀ عېب په کښې وى، مالِک خُدائ د دې کار نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4930, 'Deuteronomy 17:2', 'Deuteronomy', 17, 2, '&nbsp;کۀ تاسو واورئ چې ستاسو په يو ښار کښې څۀ سړو يا ښځو د مالِک خُدائ خِلاف ګناه کړې ده او د هغۀ سره کړے لوظ يې مات کړے دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4931, 'Deuteronomy 17:3', 'Deuteronomy', 17, 3, '&nbsp;چې هغوئ د نورو معبودانو، د نمر، سپوږمۍ، يا د ستورو عبادت او خِدمت يې کړے وى او د مالِک خُدائ د حُکم مخالفت يې کړے وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4932, 'Deuteronomy 17:4', 'Deuteronomy', 17, 4, '&nbsp;نو کۀ داسې يو خبر واورئ، نو د هغې پوره پته ولګوئ. کۀ دا رښتيا وى چې په بنى اِسرائيلو کښې داسې ګنده کار شوے وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4933, 'Deuteronomy 17:5', 'Deuteronomy', 17, 5, '&nbsp;نو هغه کس د ښار نه بهر بوځئ او سنګسار يې کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4934, 'Deuteronomy 17:6', 'Deuteronomy', 17, 6, '&nbsp;په هغه وخت کښې به هغه وژلے شى چې دوه يا د دوو نه زيات ګواهان د هغۀ خِلاف ګواهى ورکړى، خو کۀ صِرف يو ګواه وى نو هغه به نۀ شى وژلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4935, 'Deuteronomy 17:7', 'Deuteronomy', 17, 7, '&nbsp;وړومبى کاڼى به ګواهان ورولى او بيا به يې باقى نور خلق سنګسار کړى، چې ستاسو نه دا بدى لرې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4936, 'Deuteronomy 17:8', 'Deuteronomy', 17, 8, '&nbsp;کۀ داسې لانجې وى چې د هغې فېصله کول د هغه ځائ د قاضيانو دپاره ګران وى، لکه د جائيداد حقُونو يا د چا د زخمى کېدلو لانجې يا چې په قصد سره يا په غلطۍ سره د قتل په مينځ کښې فرق کول وى، نو چې داسې وشى، نو د عبادت هغه يو ځائ ته لاړ شئ چې مالِک خُدائ ستاسو خُدائ پاک خوښ کړے وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4937, 'Deuteronomy 17:9', 'Deuteronomy', 17, 9, '&nbsp;او خپله لانجه د ليوى قبيلې اِمامانو ته او په هغه وخت کښې چې کوم قاضى حاضر وى هغوئ ته يې پېش کړئ، نو هغوئ پرېږدئ چې هغه لانجه فېصله کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4938, 'Deuteronomy 17:10', 'Deuteronomy', 17, 10, '&nbsp;هغوئ به خپله فېصله وکړى او چې هغوئ تاسو ته څنګه وائى نو تاسو به هم هغه شان کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4939, 'Deuteronomy 17:11', 'Deuteronomy', 17, 11, '&nbsp;د هغوئ فېصله ومنئ او چې د کوم قانون پوره وضاحت درته وکړى نو په هغې عمل وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4940, 'Deuteronomy 17:12', 'Deuteronomy', 17, 12, '&nbsp;هر څوک چې دا جرأت وکړى او چې د قاضى يا د اِمام دا فېصله ونۀ منى نو هغه دې خامخا ووژلے شى، چې د بنى اِسرائيلو نه دا ګنده کار ختم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4941, 'Deuteronomy 17:13', 'Deuteronomy', 17, 13, '&nbsp;نو هر څوک چې د دې نه خبر شى نو وبه يريږى او د عدالت فېصلې به منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4942, 'Deuteronomy 17:14', 'Deuteronomy', 17, 14, '&nbsp;کله چې تاسو هغه مُلک ونيسئ چې مالِک خُدائ ستاسو خُدائ پاک يې تاسو له درکوى او تاسو هلته اوسېږئ، نو تاسو به ووايئ چې ستاسو نه ګېرچاپېره قومونو په شان تاسو ته هم د يو بادشاه ضرورت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4943, 'Deuteronomy 17:15', 'Deuteronomy', 17, 15, '&nbsp;ګورئ، کوم سړے چې د بادشاهۍ دپاره تاسو غوره کوئ نو چې هغه مالِک خُدائ هم غوره کړے وى. نو په کار دے چې هغه ستاسو د خپل قوم نه وى، يو مسافر خپل بادشاه مۀ جوړَوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4944, 'Deuteronomy 17:16', 'Deuteronomy', 17, 16, '&nbsp;هغه بادشاه به د ځان دپاره ډېر آسونه نۀ ساتى او هغه دې خلق مِصر ته نۀ لېږى چې آسونه په پېسو واخلى، ځکه چې مالِک خُدائ فرمائيلى دى چې د هغۀ خلق به هيڅکله واپس هلته نۀ ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4945, 'Deuteronomy 17:17', 'Deuteronomy', 17, 17, '&nbsp;د بادشاه دې ډېرې ښځې نۀ وى، ځکه چې دا به هغه د مالِک خُدائ نه واړوى، او هغه دې خپل ځان په سپينو زرو يا سرو زرو نۀ مالداره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4946, 'Deuteronomy 17:18', 'Deuteronomy', 17, 18, '&nbsp;کله چې هغه د بادشاهۍ په تخت کښېنى، نو هغه به د خپل ځان دپاره د دې قانون يو نقل وليکى، دا کار به د ليوى قبيلې د اِمامانو په وړاندې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4947, 'Deuteronomy 17:19', 'Deuteronomy', 17, 19, '&nbsp;هغه به دا کِتاب د ځان سره نزدې ساتى او ټول عُمر به يې وائى، چې د مالِک خُدائ نه يرېدل زده کړى او په وفادارۍ سره به په هغه هر څۀ باندې عمل کوى چې په دې کِتاب کښې يې حُکم راغلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4948, 'Deuteronomy 17:20', 'Deuteronomy', 17, 20, '&nbsp;نو هغه به خپل ځان د خپلو خلقو نه اوچت نۀ ګڼى او د مالِک خُدائ د حُکمونو نافرمانى به نۀ کوى. نو هغه به ډېر وخت پورې حکومت وکړى او د هغۀ اولاد به ډېره موده په بنى اِسرائيلو باندې بادشاهى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4949, 'Deuteronomy 18:1', 'Deuteronomy', 18, 1, '&nbsp;د ليوى قبيلې هيچا ته به هم په زمکه کښې حِصه نۀ ملاويږى، نۀ اِمامانو ته او نۀ يې نورو خلقو ته، د دې په ځائ هغوئ به په هغه نذرانو او قربانو ژوند تېروى کومې چې مالِک خُدائ ته ورکولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4950, 'Deuteronomy 18:2', 'Deuteronomy', 18, 2, '&nbsp;د هغوئ به خپل هيڅ ميراث نۀ وى، لکه چې نورې قبيلې يې لرى، لکه څنګه چې مالِک خُدائ وعده کړې ده چې مالِک خُدائ به په خپله د هغوئ ميراث وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4951, 'Deuteronomy 18:3', 'Deuteronomy', 18, 3, '&nbsp;کله هم چې يو څاروے يا ګډ قربانى کيږى، اِمام له به د دې اوږه، ژامه او دنننى اندامونه ورکولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4952, 'Deuteronomy 18:4', 'Deuteronomy', 18, 4, '&nbsp;هغوئ به د دې څيزونو نه وړومبۍ برخه اخلى يعنې د غلې، ميو، د زيتُونو تېلو او ستاسو د ګډو د وړو نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4953, 'Deuteronomy 18:5', 'Deuteronomy', 18, 5, '&nbsp;مالِک خُدائ ستاسو د ټولو قبيلو نه د ليوى قبيله خوښه کړه چې د اِمامانو په توګه همېشه د هغۀ خِدمت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4954, 'Deuteronomy 18:6', 'Deuteronomy', 18, 6, '&nbsp;هر يو ليوے چې وغواړى نو هغه د بنى اِسرائيلو د هر يو ښار نه د عبادت هغه يو ځائ ته راتلے شى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4955, 'Deuteronomy 18:7', 'Deuteronomy', 18, 7, '&nbsp;او هلته د يو اِمام په توګه د مالِک خُدائ خپل خُدائ پاک خِدمت کولے شى، لکه د نورو ليويانو په شان کوم چې هلته خِدمت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4956, 'Deuteronomy 18:8', 'Deuteronomy', 18, 8, '&nbsp;د نورو اِمامانو په شان به هغۀ ته هم هغه هومره خوراک ملاويږى او د هغۀ خاندان چې څۀ هم ورلېږى نو هغه د ځان دپاره کېښودے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4957, 'Deuteronomy 18:9', 'Deuteronomy', 18, 9, '&nbsp;کله چې تاسو هغه مُلک ته ورننوځئ چې مالِک خُدائ ستاسو خُدائ پاک يې تاسو له درکوى، نو چې هلته کوم قومونه دى د هغوئ په غلطو رِواجونو پسې مۀ ځئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4958, 'Deuteronomy 18:10', 'Deuteronomy', 18, 10, '&nbsp;ستاسو په مينځ کښې دې داسې کس نۀ وى چې خپل بچى په اور کښې قربانى کوى، او خپل خلق مۀ پرېږدئ چې د غېبو په خبرو عمل وکړى، يا فال وګورى يا په منتر پسې وګرځى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4959, 'Deuteronomy 18:11', 'Deuteronomy', 18, 11, '&nbsp;يا تعويذ استعمال کړى، د ښاپېرو په ذريعه کار وکړى او هغوئ مۀ پرېږدئ چې د مړو روحونو سره مشورې وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4960, 'Deuteronomy 18:12', 'Deuteronomy', 18, 12, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک د هغه خلقو نه کرکه کوى څوک چې دا حرام کارونه کوى، نو ځکه مالِک خُدائ به هغه قومونه وشړى چې تاسو مخ په وړاندې ځئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4961, 'Deuteronomy 18:13', 'Deuteronomy', 18, 13, '&nbsp;د مالِک خُدائ سره پوره وفادار اوسئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4962, 'Deuteronomy 18:14', 'Deuteronomy', 18, 14, '&nbsp;بيا موسىٰ وفرمائيل، ”په هغه مُلک کښې، کوم چې زر تاسو قبضه کړئ، خلق د غېبو خبرې کوونکو او فالونو کتونکو په نصيحت عمل کوى، خو مالِک خُدائ ستاسو خُدائ پاک اجازت نۀ درکوى چې تاسو داسې وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4963, 'Deuteronomy 18:15', 'Deuteronomy', 18, 15, '&nbsp;خو هغه به تاسو له زما په شان يو پېغمبر راولېږى چې هغه به ستاسو د خپلو خلقو نه وى او تاسو به د هغۀ تابعدارى کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4964, 'Deuteronomy 18:16', 'Deuteronomy', 18, 16, '&nbsp;په کومه ورځ چې تاسو د سينا غرۀ سره راغونډ وئ، تاسو زارى وکړه چې مونږ نۀ غواړُو چې د مالِک خُدائ خبرې بيا واورو يا د جلال شُغلې وګورو، ځکه چې تاسو يرېدلئ چې مړۀ به شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4965, 'Deuteronomy 18:17', 'Deuteronomy', 18, 17, '&nbsp;نو مالِک خُدائ ما ته وفرمائيل چې هغوئ صحيح سوال کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4966, 'Deuteronomy 18:18', 'Deuteronomy', 18, 18, '&nbsp;زۀ به هغوئ له د هغوئ د خپلو خلقو نه ستا په شان يو پېغمبر ورولېږم، زۀ به هغۀ ته وښايم چې هغه به څۀ وائى او زۀ چې کوم حُکم ورکوم نو هم هغه شان به يې خلقو ته ورسوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4967, 'Deuteronomy 18:19', 'Deuteronomy', 18, 19, '&nbsp;هغه به زما په نوم خبرې کوى او هر څوک چې د هغۀ د منلو نه اِنکار وکړى نو سزا به ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4968, 'Deuteronomy 18:20', 'Deuteronomy', 18, 20, '&nbsp;خو چې کله ما حُکم نۀ وى ورکړے او يو پېغمبر دا جرأت وکړى چې زما په نوم پېغام ورکړى، نو خامخا به وژلے شى او هغه پېغمبر به هم وژلے شى چې د نورو معبودانو په نوم خبرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4969, 'Deuteronomy 18:21', 'Deuteronomy', 18, 21, '&nbsp;مونږ څنګه دا وئيلے شُو چې د يو پېغمبر پېغام د مالِک خُدائ نه نۀ دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4970, 'Deuteronomy 18:22', 'Deuteronomy', 18, 22, '&nbsp;کۀ يو پېغمبر د مالِک خُدائ په نوم خبرې وکړى او چې کومه خبره يې کړې وى او رښتيا نۀ شى، نو بيا دا د مالِک خُدائ پېغام نۀ دے. هغه پېغمبر په خپل اختيار خبرې کړې دى او تاسو له په کار دى چې د هغۀ نه ونۀ يرېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4971, 'Deuteronomy 19:1', 'Deuteronomy', 19, 1, '&nbsp;کله چې مالِک خُدائ ستاسو خُدائ پاک هغه خلق تباه کړى چې زمکه يې تاسو له درکوى او چې د هغوئ ښارونه او کورونه ونيسئ او هلته اوسېږئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4972, 'Deuteronomy 19:4', 'Deuteronomy', 19, 4, '&nbsp;کۀ څوک يو کس په غلطۍ سره ووژنى چې هغه يې دشمن نۀ وى، نو هغه د دې ښارونو نه يو ښار ته تښتېدلے شى چې بچ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4973, 'Deuteronomy 19:5', 'Deuteronomy', 19, 5, '&nbsp;کۀ دوه سړى د لرګو وهلو دپاره ځنګل ته لاړ شى او د هغوئ نه يو کس يوه ونه وهى او تبر د لاسکى نه ووځى او هغه بل کس ووژنى، نو د پناه دپاره د دې ښارونو نه يو ته تښتېدلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4974, 'Deuteronomy 19:6', 'Deuteronomy', 19, 6, '&nbsp;خو کۀ صِرف يو ښار وے او هغې ته فاصله هم ډېره وے، نو کېدے شى چې د هغه کس بدل اخستونکى خپلوان يې ونيسى او په غصه کښې يو بې‌ګناه ګاونډى ووژنى. خو په غلطۍ سره هغۀ خپل ګاونډى مړ کړو چې دشمن يې نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4975, 'Deuteronomy 19:7', 'Deuteronomy', 19, 7, '&nbsp;نو ځکه زۀ حُکم درکوم چې درې ښارونه بېل کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4976, 'Deuteronomy 19:8', 'Deuteronomy', 19, 8, '&nbsp;کله چې مالِک خُدائ ستاسو خُدائ پاک ستاسو علاقه پراخه کړى، لکه څنګه چې هغۀ ستاسو پلار نيکۀ ته فرمائيلى دى او هغه ټول مُلک درکړى چې هغۀ يې وعده کړې ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4977, 'Deuteronomy 19:9', 'Deuteronomy', 19, 9, '&nbsp;بيا تاسو درې نور ښارونه خوښ کړئ. کۀ تاسو هغه هر څۀ کوئ چې نن يې زۀ حُکم درکوم او د مالِک خُدائ خپل خُدائ پاک سره مينه کوئ او د هغۀ د اصُولو په مطابق ژوند تېروئ نو هغه به تاسو له دا مُلک درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4978, 'Deuteronomy 19:10', 'Deuteronomy', 19, 10, '&nbsp;هم دغه شان وکړئ، نو چې بې‌ګناه خلق نۀ مرى او د هغوئ د وژلو ګناه ستاسو په غاړه نۀ وى، په هغه مُلک کښې چې مالِک خُدائ يې تاسو له درکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4979, 'Deuteronomy 19:11', 'Deuteronomy', 19, 11, '&nbsp;خو کۀ يو کس د خپل ګاونډى سره دشمنى وى او قصداً په هغۀ حمله وکړى او وې وژنى او بيا د پناه دپاره د دې ښارونو نه يو ښار ته وتښتى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4980, 'Deuteronomy 19:12', 'Deuteronomy', 19, 12, '&nbsp;نو په داسې حالت کښې دې د هغۀ د ښار مشران هغه راوغواړى او د هغه کس خپلوانو ته دې په حواله کړى کوم چې د قتل د بدل اخستلو خواهش کوى، نو چې هغوئ يې ووژنې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4981, 'Deuteronomy 19:13', 'Deuteronomy', 19, 13, '&nbsp;په هغۀ هيڅ رحم مۀ کوئ. او بنى اِسرائيل د بې‌ګناه وينې توئيدلو نه پاک کړئ، نو په دې سره به ستاسو هر يو کار سم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4982, 'Deuteronomy 19:14', 'Deuteronomy', 19, 14, '&nbsp;د خپل ګاونډى د جائيداد د حد کاڼے مۀ بې‌ځايه کوئ، کوم چې د مخکښې نه په هغه مُلک کښې لګېدلے وى چې مالِک خُدائ ستاسو خُدائ پاک يې تاسو له درکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4983, 'Deuteronomy 19:15', 'Deuteronomy', 19, 15, '&nbsp;د يو سړى مجرم ثابِتولو دپاره به يو ګواه کافى نۀ وى، بلکې د هغۀ مجرم ثابِتولو دپاره به د دوو يا درېو ګواهانو پېش کول لازمى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4984, 'Deuteronomy 19:16', 'Deuteronomy', 19, 16, '&nbsp;کۀ څوک د دروغو اِلزام په وجه بل کس ته نقصان رسولو کوشش وکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4985, 'Deuteronomy 19:17', 'Deuteronomy', 19, 17, '&nbsp;نو دواړه به د عبادت هغه يو ځائ ته ځى او د هغه وخت مقرر شوى قاضيان او اِمامان به د هغوئ فېصله وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4986, 'Deuteronomy 19:18', 'Deuteronomy', 19, 18, '&nbsp;قاضيان به د دې معاملې پوره معلومات وکړى، او کۀ چا په خپل اِسرائيلى باندې د دروغو اِلزام لګولے وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4987, 'Deuteronomy 19:19', 'Deuteronomy', 19, 19, '&nbsp;هغۀ ته به هغه سزا ملاويږى چې د څۀ اراده چې يې د بل دپاره لرله. نو داسې به تاسو د دې بدۍ نه خلاص شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4988, 'Deuteronomy 19:20', 'Deuteronomy', 19, 20, '&nbsp;بيا به هر يو کس خبر شى چې څۀ وشول، هغوئ به ويريږى او هيڅ څوک به هم بيا داسې بد عمل نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4989, 'Deuteronomy 19:21', 'Deuteronomy', 19, 21, '&nbsp;په داسې معامِلو کښې هيڅ رحم مۀ کوئ، د ژوند په بدل کښې به د ژوند سزا وى، د سترګې په بدل کښې د سترګې، د غاښ په بدل کښې د غاښ، د لاس په بدل کښې د لاس، پښې په بدل کښې به د پښې سزا وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4990, 'Deuteronomy 20:1', 'Deuteronomy', 20, 1, '&nbsp;کله چې تاسو د خپلو دشمنانو خِلاف جنګ له ځئ او تاسو وګورئ چې د هغوئ جنګى ګاډۍ، آسونه او لښکر ستاسو نه زيات وى، نو د هغوئ نه مۀ يرېږئ. مالِک خُدائ ستاسو خُدائ پاک به ستاسو مل وى، چا چې د مِصر مُلک نه راوويستلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4991, 'Deuteronomy 20:2', 'Deuteronomy', 20, 2, '&nbsp;د هغې نه مخکښې چې تاسو جنګ شروع کړئ، يو اِمام دې وړاندې راشى او لښکر ته دې ووائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4992, 'Deuteronomy 20:3', 'Deuteronomy', 20, 3, '&nbsp;اے بنى اِسرائيلو. واورئ، نن تاسو جنګ له روان يئ. مۀ بې‌زړۀ کېږئ، مۀ يرېږئ، مۀ بې‌حوصلې کېږئ او نۀ چې وارخطا شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4993, 'Deuteronomy 20:4', 'Deuteronomy', 20, 4, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک ستاسو مل دے، هغه به ستاسو د دشمنانو خِلاف جنګ کوى او فتح به درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4994, 'Deuteronomy 20:5', 'Deuteronomy', 20, 5, '&nbsp;بيا به آفسران په خپل تقرير کښې فوجيانو ته ووائى، په تاسو کښې داسې څوک شته چې کور يې جوړ کړے وى، خو وقف کړے يې نۀ وى؟ کۀ داسې څوک وى، نو هغه دې کور ته لاړ شى. کۀ هغه په جنګ کښې ووژلے شى، نو بل څوک به د هغۀ کور وقف کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4995, 'Deuteronomy 20:6', 'Deuteronomy', 20, 6, '&nbsp;دلته داسې يو سړے شته، چې هغۀ د انګورو باغ کَرلے وى، خو دا موقع ورته نۀ وى مِلاو شوى چې انګور ترې نه راټول کړى؟ کۀ داسې څوک وى، نو هغه دې کور ته لاړ شى. کۀ هغه په جنګ کښې ووژلے شى، نو بل څوک به د هغۀ په ميو مزې وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4996, 'Deuteronomy 20:7', 'Deuteronomy', 20, 7, '&nbsp;دلته داسې څوک شته، چې کوژدن يې کړې وى؟ کۀ داسې څوک وى، نو هغه دې کور ته لاړ شى. ګنې، کۀ هغه په جنګ کښې ووژلے شى، نو بل څوک به د هغۀ د کوژدن شوې ښځې سره وادۀ وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4997, 'Deuteronomy 20:8', 'Deuteronomy', 20, 8, '&nbsp;آفسران به سړو ته دا هم ووائى، دلته داسې يو سړے شته، چې هغه يريږى يا يې زړۀ بائيللے وى؟ کۀ داسې څوک وى، نو هغه دې کور ته لاړ شى. ګنې، هغه به د خپل ځان په شان د نورو ملګرو زړونه هم کمزورى کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4998, 'Deuteronomy 20:9', 'Deuteronomy', 20, 9, '&nbsp;کله چې آفسران د لښکر سره خپلې خبرې خلاصې کړى، نو د هرې قبيلې دپاره به مشران خوښ کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4999, 'Deuteronomy 20:10', 'Deuteronomy', 20, 10, '&nbsp;کله چې تاسو په يو ښار باندې حمله کوئ، نو وړومبے هغه خلقو ته د تسليمېدو موقع ورکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5000, 'Deuteronomy 20:11', 'Deuteronomy', 20, 11, '&nbsp;کۀ هغوئ دروازې کولاو کړى او تسليم شى، نو هغوئ به ټول ستاسو غلامان وى او ستاسو دپاره به بېګار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');